import{_ as s,o as i,c as a,a6 as n}from"./chunks/framework.BBdhcoHf.js";const k=JSON.parse('{"title":"ADR-017: Cloud SDK Design","description":"","frontmatter":{},"headers":[],"relativePath":"adr/017-cloud-sdk-design.md","filePath":"adr/017-cloud-sdk-design.md","lastUpdated":1772729358000}'),t={name:"adr/017-cloud-sdk-design.md"};function o(r,e,d,l,c,p){return i(),a("div",null,[...e[0]||(e[0]=[n(`<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /adr/017-cloud-sdk-design.md for this page in Markdown format</div><h1 id="adr-017-cloud-sdk-design" tabindex="-1">ADR-017: Cloud SDK Design <a class="header-anchor" href="#adr-017-cloud-sdk-design" aria-label="Permalink to “ADR-017: Cloud SDK Design”">​</a></h1><ul><li><strong>Date</strong>: 2026-02-27</li><li><strong>Status</strong>: Accepted</li><li><strong>Affects</strong>: Runtime, SDK</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p><code>relay.sideband.cloud</code> embeds a time-limited JWT in every WebSocket URL (<code>?token=&lt;jwt&gt;</code>). <code>PeerOptions.endpoint</code> is a static string — reconnects reuse it unchanged, causing 401 rejections when the token expires. Daemon presence tokens also expire (1 hour) with no renewal mechanism, and users had to decode the JWT <code>sid</code> claim manually to construct relay URLs.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><h3 id="_1-negotiator-getconnectionparams-—-dynamic-endpoint-per-attempt" tabindex="-1">1. <code>Negotiator.getConnectionParams()</code> — dynamic endpoint per attempt <a class="header-anchor" href="#_1-negotiator-getconnectionparams-—-dynamic-endpoint-per-attempt" aria-label="Permalink to “1. Negotiator.getConnectionParams() — dynamic endpoint per attempt”">​</a></h3><p>A new optional method on the <code>Negotiator</code> interface in <code>@sideband/runtime</code>:</p><div class="language-typescript"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">interface</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> NegotiatorConnectionParams</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  endpoint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// overrides PeerOptions.endpoint for this attempt</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  headers</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Record</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// extra headers (Node.js ws only)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">interface</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Negotiator</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  getConnectionParams</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Promise</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">NegotiatorConnectionParams</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Called before each connect attempt; result scoped to that attempt (no caching). If it throws, the attempt fails and the peer retries per <code>retryPolicy</code>. Runs in sequence before <code>negotiate()</code> for the same attempt — implementors may store transient state (e.g., a fetched token) between the two calls without data races.</p><p><strong>Why not <code>endpoint</code> factory in <code>PeerOptions</code>?</strong> The negotiator that resolves an endpoint also knows how to authenticate against it. A separate factory in <code>PeerOptions</code> has no synchronization guarantee with negotiator state.</p><h3 id="_2-sideband-cloud-—-separate-package" tabindex="-1">2. <code>@sideband/cloud</code> — separate package <a class="header-anchor" href="#_2-sideband-cloud-—-separate-package" aria-label="Permalink to “2. @sideband/cloud — separate package”">​</a></h3><p>SaaS URLs and deployment-specific logic are isolated in <code>@sideband/cloud</code>. Core packages (<code>@sideband/peer</code>, <code>@sideband/runtime</code>) contain no references to <code>*.sideband.cloud</code>.</p><p>Entry points:</p><ul><li><code>connect(opts)</code> — cloud client; two auth modes (see §3)</li><li><code>listen(opts)</code> — cloud daemon; outbound relay connection with session demultiplexing</li></ul><p><strong>Why not <code>@sideband/peer/cloud</code> subpath?</strong> SaaS URLs don&#39;t belong in the open-source core — they&#39;d appear in bundle output and lock the core to a specific hosted product.</p><p><strong>Why not merge into <code>@sideband/peer</code>?</strong> The daemon path pulls in <code>@sideband/transport-ws</code> and a relay-specific mux loop, bloating browser bundles and conflating the generic SDK with a specific hosted deployment model.</p><h3 id="_3-connect-auth-modes-—-account-vs-quick-connect" tabindex="-1">3. <code>connect()</code> auth modes — account vs. Quick Connect <a class="header-anchor" href="#_3-connect-auth-modes-—-account-vs-quick-connect" aria-label="Permalink to “3. connect() auth modes — account vs. Quick Connect”">​</a></h3><p><code>connect()</code> accepts two mutually exclusive auth modes (discriminated union at the type level):</p><p><strong>Account path</strong> (<code>{ daemonId, getAccessToken }</code>): standard persistent sessions. A fresh relay session is fetched from <code>api.sideband.cloud</code> on every connect attempt (relay rejects reused sessionIds with 409 — treated as retryable ghost-socket collision here). <code>daemonId</code> is known upfront. Reconnects automatically on transport drops.</p><p><strong>Quick Connect path</strong> (<code>{ quickConnectCode }</code>): one-shot bootstrap using a short-lived code as the sole credential. <code>redeemQuickConnectCode()</code> is called once — it returns the relay URL, a session JWT, and the <code>daemonId</code> resolved server-side. After redeem, <code>qcRedeemed</code> is set to <code>true</code> and any further <code>getConnectionParams()</code> call throws <code>PeerError(InvalidState)</code> (fatal), preventing silent re-redeem attempts.</p><p><strong>Why consume-first?</strong> The server atomically transitions the code to <code>redeemed</code> before checking whether the daemon is online (there is no race-free pre-check). A 409 response means the code is already burned and the daemon was offline — retrying would produce a misleading 404. The SDK classifies 409 as fatal in QC mode so callers surface the true error immediately: &quot;get a new code.&quot;</p><p><strong>Why is QC non-reconnecting?</strong> QC codes are single-use by design. Persisting a session after the initial bootstrap is the account path&#39;s responsibility; QC serves the &quot;no-login&quot; first-contact scenario. Attempting auto-reconnect with a burned code would stall until <code>maxAttempts</code> is exhausted.</p><h3 id="_4-relaydaemontransport-—-inverted-transport-for-daemon-relay" tabindex="-1">4. <code>RelayDaemonTransport</code> — inverted transport for daemon relay <a class="header-anchor" href="#_4-relaydaemontransport-—-inverted-transport-for-daemon-relay" aria-label="Permalink to “4. RelayDaemonTransport — inverted transport for daemon relay”">​</a></h3><p>Daemons do not bind a local port. The relay multiplexes frames from multiple client sessions onto a single outbound WebSocket, each tagged by <code>SessionID</code>. <code>RelayDaemonTransport</code> implements <code>Transport.listen()</code> by connecting outbound and demultiplexing incoming frames by <code>SessionID</code> into virtual <code>RelayVirtualConn</code> instances.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>relay.sideband.cloud</span></span>
<span class="line"><span>    │ one outbound WebSocket per daemon</span></span>
<span class="line"><span>    │ SBRP frames multiplexed by SessionID</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>RelayDaemonTransport.listen()</span></span>
<span class="line"><span>    │ HandshakeInit (new SID) → create RelayVirtualConn → handler(vconn)</span></span>
<span class="line"><span>    │ known SID → route frame to existing RelayVirtualConn</span></span>
<span class="line"><span>    │ SID=0 Control → rate_limited: continue; other: reconnect</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>sbrpDaemonNegotiator per session → AcceptedPeer → onConnection(peer)</span></span></code></pre></div><p><code>peerListen()</code> is unchanged — it sees a stream of <code>TransportConnection</code> objects regardless of whether they come from a local server or relay mux. Slow consumers are terminated (backpressure). Consecutive malformed frames trigger reconnect with backoff (circuit breaker against log storms on protocol version mismatch).</p><p><code>listen()</code> returns <code>CloudPeerServer</code> (extends <code>PeerServer</code>) with three additional members that are only available after the first relay connection resolves:</p><div class="language-typescript"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">interface</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> CloudPeerServer</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> extends</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> PeerServer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  readonly</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> daemonId</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// \`did\` claim extracted from the presence token</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  readonly</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> relayUrl</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// e.g. &quot;wss://relay.sideband.cloud&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  createQuickConnect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">opts</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ttlSeconds</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> number</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Promise</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;{</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    code</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// short-lived QC code</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    url</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ready-to-use connect URL</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    expiresAt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ISO 8601</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }&gt;;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>daemonId</code> and <code>relayUrl</code> are read from the presence token on first connect, so they are never stale even if the daemon ID was omitted from <code>ListenOptions</code>.</p><h2 id="invariants" tabindex="-1">Invariants <a class="header-anchor" href="#invariants" aria-label="Permalink to “Invariants”">​</a></h2><ul><li><code>getConnectionParams()</code> MUST run before <code>negotiate()</code> for every attempt, in sequence.</li><li><code>@sideband/peer</code> and <code>@sideband/runtime</code> MUST NOT reference any <code>*.sideband.cloud</code> URLs.</li><li>In QC mode, <code>getConnectionParams()</code> MUST NOT be called a second time after a successful redeem.</li><li>409 from the relay in account mode is retryable; in QC mode it is fatal (code is burned).</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to “References”">​</a></h2><ul><li>ADR-013: Peer SDK Core Design Decisions</li><li>ADR-016: Relay Server Design</li><li><code>packages/runtime/src/session/types.ts</code> — <code>Negotiator</code>, <code>NegotiatorConnectionParams</code></li><li><code>packages/cloud/src/connect.ts</code> — <code>CloudClientNegotiator</code></li><li><code>packages/cloud/src/listen.ts</code> — <code>RelayDaemonTransport</code>, <code>RelayVirtualConn</code>, <code>runMux</code>, <code>CloudPeerServer</code></li></ul>`,34)])])}const g=s(t,[["render",o]]);export{k as __pageData,g as default};
